ROUTES={'Home':'home','Library Overview':'library','Observations Overview':'observation','Research Overview':'research','Knowledge & AI Overview':'knowledge','AI Chat & MCP':'ai','AI Platform Administration':'settings','Administration Overview':'administration','Photos':'photo','Sounds':'sound','Videos':'video','Documents':'document','Imports':'import','Export':'export','Collections':'collection','Notebook':'notebook','Map':'map','Science Projects':'project','Measurements & Protocols':'research','Science Dossiers':'dossier','Science Calendar':'calendar','Science Whiteboard':'whiteboard','Maritime Operations':'maritime','Observation History':'observation','Life Lists & Statistics':'life-list','Animal Records':'records','Plant & Flower Records':'plant','Marine & Freshwater Science':'maritime','Reporting':'report','AI Review':'ai','Knowledge Base':'knowledge','Taxonomy':'taxonomy','Taxonomy Resources':'gbif','Regional Knowledge':'regional','Models':'model','AI Resources':'ai','Knowledge Sources':'source','Resource Components':'settings','Enrichment Sources':'enrichment','Storage Manager':'storage','Trash Manager':'trash','Activity Center':'activity','Offline Maps':'layers','Access & Contracts':'access','Integrations':'integration','Library Types':'library','Health Check':'health','Diagnostics':'diagnostics','Updates':'update','Preferences':'preferences','Branding & Project':'branding','__help__':'help'}
def icon(name):
 q=QIcon();q.addFile(str(ROOT/f'{name}.svg'),QSize(24,24),QIcon.Mode.Normal,QIcon.State.Off);q.addFile(str(ROOT/f'{name}-active.svg'),QSize(24,24),QIcon.Mode.Selected,QIcon.State.Off);q.addFile(str(ROOT/f'{name}-active.svg'),QSize(24,24),QIcon.Mode.Active,QIcon.State.Off);return q
def route_icon(route):return icon(ROUTES.get(route,'document'))
